{"command":"$src="E:\项目_手动重构\build\final-hone-dh1b_5mf\project\workspace\task"
$dst=(Get-Location).Path
Copy-Item -Path (Join-Path $src 'INPUTS.md') -Destination (Join-Path $dst 'INPUTS.md') -Force
foreach($d in 'docs','data_file','examples'){ Copy-Item -Path (Join-Path $src $d) -Destination $dst -Recurse -Force }
# verify byte-identical
Get-ChildItem -Recurse -File $src | Where-Object { $_.FullName -notmatch '\\task\\.' } | ForEach-Object {
  $rel=$_.FullName.Substring($src.Length+1)
  $t=Join-Path $dst $rel
  if(-not (Test-Path -LiteralPath $t)){ Write-Host "MISSING $rel" }
  elseif((Get-FileHash -LiteralPath $_.FullName).Hash -ne (Get-FileHash -LiteralPath $t).Hash){ Write-Host "DIFF $rel" }
}
Write-Host "verify done"
